import datetime, enum, click
from click.testing import CliRunner
r = CliRunner()

# 1. Reusing one @command(...) decorator object on two functions
deco = click.command(params=[click.Option(["--shared"])])
@deco
def first():
    """First doc."""
@deco
def second():
    """Second doc."""
print("1 help:", repr(first.help), repr(second.help))
print("1 params:", [p.name for p in first.params], [p.name for p in second.params])

# 2. Type inferred from a non-basic default
class Color(enum.Enum):
    RED = "r"
@click.command()
@click.option("--when", default=datetime.datetime(2020, 1, 2))
@click.option("--color", default=Color.RED)
def c(when, color):
    click.echo(f"when={when!r} color={color!r}")
print("2:", r.invoke(c, []).output.strip())

# 3. FuncParamType converter raising TypeError instead of ValueError
def needs_int(v):
    return 10 / int(v) if v != "x" else None + 1
@click.command()
@click.option("--v", type=needs_int)
def d(v):
    pass
res = r.invoke(d, ["--v", "x"])
print("3:", res.exit_code, type(res.exception).__name__, res.output.strip())

# 4. Decorator order -> params order
@click.command()
@click.option("--a")
@click.option("--b")
@click.argument("c")
def e(a, b, c): pass
print("4:", [p.name for p in e.params])
